INSERT INTO `rag_document_text` VALUES (1,3,'\n\n','2026-07-26 06:48:37'),(2,4,'\n\nAI-Based Drought Prediction\nUsing Multi-Source Satellite\nData and Machine Learning\nModels\nby Trishul Swamy H.m\nSubmission date: 05-May-2026 10:34AM (UTC+0530)\nSubmission ID: 2951998795\nFile name: FINAL_aisd_research_1_1.pdf (419.28K)\nWord count: 3857\nCharacter count: 24549\n\n2\n3\n3\n558\n13\n15\n16\n19\n\n2\n2\n\n\n\n\n\n3\n9\n10\n17\n\n1\n1\n2\n2\n2\n6\n7\n11\n12\n14\n20\n21\n22\n\n1\n1\n1\n4\n18\n\n\n\n\n\n10%\nSIMILARITY INDEX\n4%\nINTERNET SOURCES\n8%\nPUBLICATIONS\n4%\nSTUDENT PAPERS\n1\n1%\n2\n1%\n3\n1%\n4\n1%\n5\n1%\n6\n1%\n7\n1%\nAI-Based Drought Prediction Using Multi-Source Satellite Data\nand Machine Learning Models\nORIGINALITY REPORT\nPRIMARY SOURCES\nPaolo Ferro, Harinadh Vemanaboina, Chander\nPrakash. \"Computational Techniques and\nSmart Manufacturing\", CRC Press, 2026\nPublication\nK. V. Sambasivarao, Anasuya Sesha Roopa\nDevi Bhima. \"Artificial Intelligence,\nComputational Intelligence, and Inclusive\nTechnologies - Proceedings of International\nConference on Artificial Intelligence,\nComputational Intelligence, and Inclusive\nTechnologies (ICRAIC2IT – 2025)\", CRC Press,\n2026\nPublication\nwww.mdpi.com\nInternet Source\nSubmitted to Brunel University\nStudent Paper\nMalaika Vijay, Amith Kashyap, Aushim\nNagarkatti, Shruti Mohanty, Rajasekar Mohan,\nNiranjana Krupa. \"Extreme Gradient Boosting\nClassification of Motor Imagery using\nCommon Spatial Patterns\", 2020 IEEE 17th\nIndia Council International Conference\n(INDICON), 2020\nPublication\njicrcr.com\nInternet Source\nSubmitted to University of Northumbria at\nNewcastle\n\n8\n<1%\n9\n<1%\n10\n<1%\n11\n<1%\n12\n<1%\n13\n<1%\n14\n<1%\n15\n<1%\n16\n<1%\n17\n<1%\n18\n<1%\n19\n<1%\nStudent Paper\nJayashree R, Vinay S K. \"A Jaccards Similarity\nScore Based Methodology for Kannada Text\nDocument Summarization\", 2020\nInternational Conference on Advances in\nComputing, Communication & Materials\n(ICACCM)